const inputItem = $input.first().json || {};
const headers = inputItem.headers || {};
const body = inputItem.body || {};
const data = body.data || {};
const eventCode = String(data.eventCode ?? '');
const webhookId = headers['webhook-id'] || headers['x-request-id'] || data.id || null;

const entryInvalidCodes = {
  '7000': 'Invalid Entry – No Access',
  '7001': 'Invalid Entry – Identity expired',
  '7002': 'Invalid Entry – Unassigned Access Zone',
  '7003': 'Invalid Entry – Access Group, Invalid Schedule',
  '7004': 'Invalid Entry – Access Group, expired',
  '7005': 'Invalid Entry – Anti Pass-back Violation',
  '7006': 'Invalid Entry – Anti tail gate Violation',
  '7007': 'Invalid Entry – Invalid Pin',
  '7008': 'Invalid Entry – Dual Credential Timeout',
  '7009': 'Invalid Entry – Dual Credential Failed',
  '7010': 'Invalid Entry – Dual Authorization Timeout',
  '7011': 'Invalid Entry – Dual Authorization Failed',
  '7013': 'Invalid Entry – First Card Unlock',
  '7014': 'Invalid Entry – Max People Count',
  '7015': 'Invalid Entry – Interlock Active',
  '7016': 'Invalid Entry – Controller Hub Down'
};

const exitInvalidCodes = {
  '7100': 'Invalid Exit – No Access',
  '7101': 'Invalid Exit – Identity expired',
  '7102': 'Invalid Exit – Unassigned Access Zone',
  '7103': 'Invalid Exit – Access Group, Invalid Schedule',
  '7104': 'Invalid Exit – Access Group, expired',
  '7105': 'Invalid Exit – Anti Pass-back Violation',
  '7106': 'Invalid Exit – Anti tail gate Violation',
  '7107': 'Invalid Exit – Invalid Pin',
  '7108': 'Invalid Exit – Dual Credential Timeout',
  '7109': 'Invalid Exit – Dual Credential Failed',
  '7110': 'Invalid Exit – Dual Authorization Timeout',
  '7111': 'Invalid Exit – Dual Authorization Failed',
  '7113': 'Invalid Exit – First Card Unlock',
  '7114': 'Invalid Exit – Max People Count',
  '7115': 'Invalid Exit – Interlock Active',
  '7116': 'Invalid Exit – Controller Hub Down'
};

const mappingTable = {
  // (1) Access-Related
  '5001': { incidentType: 'door_held_open', severity: 'medium', isIdle: false, eventName: 'Door Left Opened' },
  '5002': { incidentType: 'door_forced_open', severity: 'high', isIdle: false, eventName: 'Door Force Opened' },
  '5003': { incidentType: 'door_held_open', severity: 'low', isIdle: true, pairCode: ['5001', '5002'], eventName: 'Door Closed' },
  '8000': { incidentType: 'door_held_open', severity: 'low', isIdle: true, pairCode: ['5001', '5002'], eventName: 'Door Closed' },

  // (2) Tamper & Intrusion
  '4001': { incidentType: 'reader_tamper', severity: 'high', isIdle: false, eventName: 'Logical Reader Tamper ACTIVE' },
  '4000': { incidentType: 'reader_tamper', severity: 'low', isIdle: true, pairCode: ['4001'], eventName: 'Logical Reader Tamper IDLE' },
  '1003': { incidentType: 'panel_tamper', severity: 'critical', isIdle: false, eventName: 'Panel Tamper ACTIVE' },
  '1002': { incidentType: 'panel_tamper', severity: 'low', isIdle: true, pairCode: ['1003'], eventName: 'Panel Tamper IDLE' },

  // (3) System & Hardware
  '1007': { incidentType: 'power_failure', severity: 'high', isIdle: false, eventName: 'AC Power Failure' },
  '1006': { incidentType: 'power_failure', severity: 'low', isIdle: true, pairCode: ['1007'], eventName: 'AC Power Recovered' },
  '1000': { incidentType: 'power_failure', severity: 'high', isIdle: false, eventName: 'Power Up / Reset' },
  '1004': { incidentType: 'battery_low', severity: 'medium', isIdle: false, eventName: 'Battery Status Low' },
  '1005': { incidentType: 'battery_low', severity: 'high', isIdle: false, eventName: 'Battery Status Critically Low' },
  '1011': { incidentType: 'comm_failure', severity: 'high', isIdle: false, eventName: 'Server communication down' },
  '1020': { incidentType: 'comm_failure', severity: 'medium', isIdle: false, eventName: 'Event buffer limit reached' },
  '4003': { incidentType: 'reader_offline', severity: 'high', isIdle: false, eventName: 'Logical Reader offline' },
  '1013': { incidentType: 'comm_failure', severity: 'high', isIdle: false, eventName: 'Interface down' },
  '1019': { incidentType: 'comm_failure', severity: 'high', isIdle: false, eventName: 'Controller hub down' },
  '1009': { incidentType: 'hardware_error', severity: 'high', isIdle: false, eventName: 'Memory error' },

  // (4) Environmental & Safety
  '5014': { incidentType: 'emergency_exit', severity: 'critical', isIdle: false, eventName: 'Door Emergency Release Activated' },
  '5015': { incidentType: 'emergency_exit', severity: 'low', isIdle: true, pairCode: ['5014'], eventName: 'Door Emergency Release Deactivated' }
};

for (const [code, name] of Object.entries(entryInvalidCodes)) {
  mappingTable[code] = { incidentType: 'invalid_credential', severity: 'medium', isIdle: false, eventName: name };
}
for (const [code, name] of Object.entries(exitInvalidCodes)) {
  mappingTable[code] = { incidentType: 'invalid_credential', severity: 'medium', isIdle: false, eventName: name };
}

const mapping = mappingTable[eventCode] || null;
const isIgnored = !mapping;

const deviceName = data.eventPointName || data.eventSourceName || 'Proscalar Device';
const eventName = mapping ? mapping.eventName : (data.message || `Unmapped Event (${eventCode})`);
const title = `${eventName} - ${deviceName}`;
const eventTimestamp = data.eventTimestamp || body.timestamp || headers['webhook-timestamp'] || new Date().toISOString();

return [{
  json: {
    type: body.type,
    eventCode,
    webhookId,
    isIgnored,
    isIdleCode: mapping ? mapping.isIdle : false,
    activePairCode: mapping ? (mapping.pairCode || null) : null,
    incidentType: mapping ? mapping.incidentType : 'ignored',
    severity: mapping ? mapping.severity : 'low',
    deviceName,
    title,
    eventSourceId: data.eventSourceId,
    eventPointId: data.eventPointId,
    eventTimestamp,
    message: data.message || eventName,
    rawData: data
  }
}];

const inputItem = $input.first().json || {};
const headers = inputItem.headers || {};
const body = inputItem.body || {};
const data = body.data || {};
const rawGroupCode = data.groupEventCode;
const groupCode = rawGroupCode !== null && rawGroupCode !== undefined ? String(rawGroupCode) : '';
const accessZones = Array.isArray(data.accessZones) ? data.accessZones : [];
const webhookId = headers['webhook-id'] || headers['x-request-id'] || null;
const revision = data.revision !== undefined && data.revision !== null ? Number(data.revision) : null;

// Per Proscalar spec: 12001 is single-zone normal, NOT whole-group resolution.
// Only resolve group alarm on 12009 (Group Normal) or 12015 (Group Reset).
const isResolution = ['12009', '12015'].includes(groupCode);

const isFire = accessZones.some(z => String(z.type).toUpperCase() === 'FIRE');
const isPanic = accessZones.some(z => String(z.type).toUpperCase() === 'PANIC');
const isMedical = accessZones.some(z => String(z.type).toUpperCase() === 'MEDICAL');
const isSafetyCategory = (isFire || isPanic || isMedical);

const hasTriggeredZone = accessZones.some(z => String(z.state).toUpperCase() === 'TRIGGERED');
const allZonesAcknowledged = accessZones.length > 0 && accessZones.every(z => String(z.state).toUpperCase() === 'ACKNOWLEDGED');

// Trigger creation on 12008, or if a safety zone is actively TRIGGERED
const isTrigger = groupCode === '12008' || (isSafetyCategory && hasTriggeredZone && !isResolution);
// Non-safety groups may auto-resolve when all zones are ACKNOWLEDGED by an operator
const isAckResolution = !isSafetyCategory && allZonesAcknowledged;

// Ignore operator-only / null groupEventCode transitions that neither trigger nor resolve
const isIgnored = !isResolution && !isAckResolution && !isTrigger;

let incidentType = 'group_alarm';
let severity = 'medium';

if (isFire) {
  incidentType = 'fire_alarm';
  severity = 'critical';
} else if (isPanic) {
  incidentType = 'panic_alarm';
  severity = 'critical';
} else if (isMedical) {
  incidentType = 'medical_alarm';
  severity = 'high';
} else if (groupCode === '12008') {
  incidentType = 'group_alarm';
  severity = 'high';
}

const deviceName = data.eventSourceName || data.name || 'Alarm Monitoring Group';
const title = `${data.name || 'ALARM GROUP'} - ${incidentType.toUpperCase()}`;
const eventTimestamp = data.eventTimestamp || body.timestamp || headers['webhook-timestamp'] || new Date().toISOString();

return [{
  json: {
    type: body.type,
    webhookId,
    revision,
    alarmGroupId: data.alarmGroupId,
    groupEventCode: groupCode || null,
    isIgnored,
    isResolution: isResolution || isAckResolution,
    isTrigger,
    isSafetyCategory,
    incidentType,
    severity,
    title,
    deviceName,
    eventTimestamp,
    rawData: data
  }
}];

/**
 * n8n Code node: TU door held/forced + close idle suppress Mon–Fri 09:00–17:00 Asia/Kuala_Lumpur.
 * Place after "Classify Event Code". Sets isScheduleFiltered on the item; downstream IF skips iMOPS POST.
 */
const item = $input.first().json || {};
const eventCode = String(item.eventCode ?? '');

/** Proscalar: held open, forced open, door closed (idle pair) */
const SUPPRESS_EVENT_CODES = new Set(['5001', '5002', '5003', '8000']);
const TIMEZONE = 'Asia/Kuala_Lumpur';
const START_MINUTES = 9 * 60;
const END_MINUTES = 17 * 60;

function weekdayAndMinutes(iso) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return null;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    weekday: 'short',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(d);
  const pick = (type) => parts.find((p) => p.type === type)?.value;
  const weekday = pick('weekday');
  const dayMap = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  const day = dayMap[weekday];
  if (day === undefined) return null;
  const minutes = Number(pick('hour')) * 60 + Number(pick('minute'));
  if (Number.isNaN(minutes)) return null;
  return { day, minutes };
}

function isOfficeSuppressWindow(iso) {
  const local = weekdayAndMinutes(iso);
  if (!local) return false;
  if (local.day < 1 || local.day > 5) return false;
  return local.minutes >= START_MINUTES && local.minutes <= END_MINUTES;
}

const eventTimestamp = item.eventTimestamp || new Date().toISOString();
const isScheduleFiltered =
  SUPPRESS_EVENT_CODES.has(eventCode) && isOfficeSuppressWindow(eventTimestamp);

return [
  {
    json: {
      ...item,
      isScheduleFiltered,
      scheduleFilterReason: isScheduleFiltered
        ? 'door_mon_fri_09_17_asia_kuala_lumpur'
        : null,
    },
  },
];
